/* Находим email администратора charter-школы с минимальной численностью учащихся K-12 */
SELECT s."admemail1"
FROM "frpm" AS f
JOIN "schools" AS s
  ON s."cdscode" = f."cdscode"
WHERE f."Charter School (Y/N)" = 1
  AND f."Enrollment (K-12)" = (
    /* Минимальное количество учащихся среди charter-школ */
    SELECT MIN(f2."Enrollment (K-12)")
    FROM "frpm" AS f2
    WHERE f2."Charter School (Y/N)" = 1
  )
LIMIT 1;

/* Найти число совершённых преступлений в 1995 году для округа аккаунта 532 */
SELECT d."a15"
FROM "account" AS a
JOIN "district" AS d
  ON a."district_id" = d."district_id"
WHERE a."account_id" = 532;

/* Посчитать общее число атомов в молекулах с тройной связью, если атом — фосфор или бром */
SELECT COUNT(*) AS "total_atoms"
FROM "atom" AS a
WHERE a."molecule_id" IN (
    SELECT DISTINCT b."molecule_id"
    FROM "bond" AS b
    WHERE b."bond_type" = '#'
)
AND a."element" IN ('p', 'br');

/* Cards without multiple faces: find illustrator of the card art with the highest converted mana cost */
SELECT c."artist"
FROM "cards" AS c
WHERE c."side" IS NULL
ORDER BY CAST(c."convertedmanacost" AS REAL) DESC NULLS LAST
LIMIT 1;

/* Count cards designed by John Avon with non-foil card kingdom id */
SELECT COUNT(*) AS "count"
FROM "cards" AS c
WHERE c."artist" LIKE '%John Avon%'
  AND c."cardkingdomid" IS NOT NULL
  AND c."cardkingdomfoilid" IS NULL;

/* Подсчет карт с originaltype = "Summon - Angel" и subtype не равен "Angel" */
SELECT
    COUNT(*) AS "count"
FROM "cards" AS "c"
WHERE TRIM(COALESCE("c"."originaltype", '')) = 'Summon - Angel'
  AND TRIM(COALESCE("c"."subtypes", '')) <> 'Angel';

/* Подсчёт карт с чёрной рамкой и вывод их идентификаторов */
SELECT
    COUNT(*) OVER () AS "count_black_border_cards",
    c."id" AS "card_id"
FROM "cards" AS c
WHERE LOWER(c."bordercolor") = 'black';

/* Найти id набора с максимальным количеством карт */
SELECT "s"."id"
FROM "sets" AS "s"
WHERE "s"."basesetsize" = (
    SELECT MAX("s2"."basesetsize")
    FROM "sets" AS "s2"
);

/* Count cards designed by Aaron Miller that are incredibly powerful */
SELECT COUNT(*) AS "count"
FROM "cards" AS c
WHERE c."artist" LIKE 'Aaron Miller'
  AND c."cardkingdomfoilid" IS NOT NULL
  AND c."cardkingdomid" IS NOT NULL;

/* Найти Commander-набор с максимальным totalsetsize и вернуть его id */
SELECT s."id"
FROM "sets" AS s
WHERE s."type" = 'commander'
  AND s."totalsetsize" = (
    SELECT MAX(s2."totalsetsize")
    FROM "sets" AS s2
    WHERE s2."type" = 'commander'
  );

/* Процент французских Story Spotlight карт */
SELECT
    100.0 * COUNT(CASE WHEN LOWER(TRIM("language")) = 'french' THEN 1 END) / NULLIF(COUNT("id"), 0) AS "percentage"
FROM "cards"
WHERE "isstoryspotlight" = 1;

/* Возраст пользователя с максимальной репутацией */
SELECT u."age"
FROM "users" AS u
ORDER BY u."reputation" DESC, u."id" ASC
LIMIT 1;

/* Бейджи пользователей с минимальной репутацией */
SELECT DISTINCT
    "b"."name"
FROM "badges" AS "b"
JOIN "users" AS "u"
    ON "u"."id" = "b"."userid"
WHERE "u"."reputation" = (
    SELECT MIN("u2"."reputation")
    FROM "users" AS "u2"
);

/* Count users with more than 5 badges */
SELECT COUNT(*) AS "user_count"
FROM (
    SELECT "b"."userid"
    FROM "badges" AS "b"
    GROUP BY "b"."userid"
    HAVING COUNT("b"."name") > 5
) AS "t";

SELECT
  /* Количество просмотров поста с точным заголовком */
  p."viewcount"
FROM "posts" AS p
WHERE p."title" = 'Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer";

SELECT
    /* Разница процентов бейджей Student между 2010 и 2011 годами */
    (
        (
            COUNT(*) FILTER (
                WHERE "b"."name" = 'Student'
                  AND EXTRACT(YEAR FROM "b"."date"::date) = 2010
            )::numeric
            / NULLIF(COUNT(*) FILTER (WHERE "b"."name" = 'Student'), 0)
        ) * 100
        -
        (
            COUNT(*) FILTER (
                WHERE "b"."name" = 'Student'
                  AND EXTRACT(YEAR FROM "b"."date"::date) = 2011
            )::numeric
            / NULLIF(COUNT(*) FILTER (WHERE "b"."name" = 'Student'), 0)
        ) * 100
    ) AS "percentage_difference"
FROM "badges" AS "b";

SELECT
    /* Процент постов Community, использующих тег r */
    100.0 * COUNT(DISTINCT CASE
        WHEN LOWER(TRIM("p"."tags")) LIKE '%<r>%' THEN "p"."id"
        END
    ) / NULLIF(COUNT(DISTINCT "p"."id"), 0) AS "percentage"
FROM "posts" AS "p"
JOIN "users" AS "u"
    ON "u"."id" = "p"."owneruserid"
WHERE "u"."displayname" = 'Community';

SELECT DISTINCT "p"."id"
FROM "publisher" AS "p"
WHERE "p"."publisher_name" LIKE 'Star Trek';

/* Find the power ID for cryokinesis */
SELECT "sp"."id"
FROM "superpower" AS "sp"
WHERE "sp"."power_name" LIKE 'cryokinesis';

/* Total number of superheroes without full name */
SELECT COUNT(*) AS "total_number_of_superheroes_without_full_name"
FROM "superhero" AS "s"
WHERE "s"."full_name" IS NULL;

/* Разница между весом Emil Blonsky и Charles Chandler */
SELECT
    COALESCE(SUM(CASE WHEN "s"."full_name" = 'Emil Blonsky' THEN "s"."weight_kg" END), 0)
    - COALESCE(SUM(CASE WHEN "s"."full_name" = 'Charles Chandler' THEN "s"."weight_kg" END), 0) AS "difference"
FROM "superhero" AS "s";

SELECT COUNT(*) AS "count"
FROM "member" AS m
WHERE m."position" LIKE 'President';

/* Студент, который сгенерировал доход более 40 */
SELECT DISTINCT m."first_name", m."last_name"
FROM "member" AS m
JOIN "income" AS i
  ON m."member_id" = i."link_to_member"
WHERE CAST(i."amount" AS NUMERIC) > 40;

/* Expenses of the budget with the lowest remaining */
SELECT
  e."expense_description"
FROM "expense" AS e
JOIN "budget" AS b
  ON e."link_to_budget" = b."budget_id"
WHERE b."remaining" = (
  SELECT MIN(b2."remaining")
  FROM "budget" AS b2
);

SELECT DISTINCT
  /* full name */ m."first_name",
  /* full name */ m."last_name",
  /* major */ maj."major_name"
FROM "expense" AS e
JOIN "member" AS m
  ON e."link_to_member" LIKE m."member_id"
LEFT JOIN "major" AS maj
  ON m."link_to_major" LIKE maj."major_id"
WHERE CAST(e."cost" AS NUMERIC) > 100;

/* Ratio of customers who pay in EUR against customers who pay in CZK */
SELECT
    COUNT(*) FILTER (WHERE "currency" = 'EUR')::numeric
    / NULLIF(COUNT(*) FILTER (WHERE "currency" = 'CZK'), 0) AS "ratio"
FROM "customers";

/* Count discount gas stations in Czech Republic minus Slovakia */
SELECT
    COUNT(DISTINCT CASE WHEN "g"."country" = 'CZE' AND LOWER("g"."segment") = 'discount' THEN "g"."gasstationid" END)
    - COUNT(DISTINCT CASE WHEN "g"."country" = 'SVK' AND LOWER("g"."segment") = 'discount' THEN "g"."gasstationid" END) AS "difference"
FROM "gasstations" AS "g";

/* Средняя цена транзакций для клиентов с валютой оплаты euro */
SELECT AVG(t."price") AS "average_total_price"
FROM "customers" AS c
JOIN "transactions_1k" AS t
  ON c."customerid" = t."customerid"
WHERE LOWER(c."currency") = 'euro';
